import React, { useState } from "react";
import { Calendar } from "primereact/calendar";
import { Tooltip } from "primereact/tooltip";
import { format } from 'date-fns';
import "./css/calendar.css";

const AppointmentsCalendar = ({ appointments }) => {
  const [selectedDate, setSelectedDate] = useState(null);

  const appointmentStyle = (status) => {
    switch (status) {
      case "completed":
        return { backgroundColor: "green", color: "white" };
      case "pending":
        return { backgroundColor: "yellow", color: "black" };
      case "confirmed":
        return { backgroundColor: "blue", color: "white" };
      case "cancelled":
        return { backgroundColor: "red", color: "white" };
      default:
        return {};
    }
  };

  return (
    <div>
      <Calendar
        dateFormat="mm/dd/yy"
        onChange={(e) => setSelectedDate(e.value)}
        inline
        monthNavigator
        yearNavigator
      />
      <div className="appointment-list">
        {appointments.map((appointment) => (
          <div
            key={appointment._id}
            style={appointmentStyle(appointment.status)}
            className="appointment-item"
            data-pr-tooltip={`Pet: ${appointment.pet_id.name}\nReason: ${appointment.notes}\nVet: ${appointment.vet_id.name}`}
          >
            {format(new Date(appointment.date), 'MMMM dd, yyyy')}
          </div>
        ))}
      </div>
      <Tooltip />
    </div>
  );
};

export default AppointmentsCalendar;
